  def icon(name, css: nil)
    tag.svg ICONS.fetch(name), class: class_names("icon", css), viewBox: "0 0 24 24", fill: "none", stroke: "currentColor",
      "stroke-width": 2, "stroke-linecap": "round", "stroke-linejoin": "round", aria: { hidden: true }, focusable: false
  end

  # Button or link content: an icon followed by its label.
  def with_icon(name, label, label_class: nil)
    safe_join([ icon(name), tag.span(label, class: label_class) ])
  end
